<script setup lang="ts">
import { onMounted, ref, watch } from 'vue'
import { api, type GeoReference, type ShippingLocation, type ShippingRule } from '../api'
import { formatVnd } from '../format'
import { t } from '../i18n'
const rules=ref<ShippingRule[]>([]),provinces=ref<GeoReference[]>([]),districts=ref<GeoReference[]>([]),locations=ref<ShippingLocation[]>([])
const error=ref(''),busy=ref(false),province=ref(''),district=ref(''),location=ref(''),family=ref(''),revision=ref(1)
const scope=ref<'LOCATION'|'GLOBAL'>('LOCATION')
const fee=ref(30000),priority=ref(0),zone=ref<ShippingRule['zoneCode']>('LOCAL_CORE')
async function load(){busy.value=true;error.value='';try{[rules.value,provinces.value,locations.value]=await Promise.all([api.shippingRules(),api.provinces(),api.shippingLocations()])}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{busy.value=false}}
watch(province,async value=>{district.value='';districts.value=value?await api.districts(value):[]})
async function create(){if(!province.value||!district.value||(scope.value==='LOCATION'&&!location.value))return;busy.value=true;try{await api.createShippingRule({familyId:family.value||crypto.randomUUID(),revisionNumber:revision.value,originScope:scope.value,originLocationId:scope.value==='LOCATION'?location.value:undefined,provinceCode:province.value,districtCode:district.value,zoneCode:zone.value,feeAmount:fee.value,priority:priority.value,validFrom:new Date().toISOString()});family.value='';revision.value=1;scope.value='LOCATION';await load()}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{busy.value=false}}
function nextRevision(r:ShippingRule){family.value=r.familyId;revision.value=r.revisionNumber+1;scope.value=r.originScope as 'LOCATION'|'GLOBAL';province.value=r.provinceCode;location.value=r.originLocationId??'';fee.value=r.feeAmount;priority.value=r.priority;zone.value=r.zoneCode;setTimeout(()=>district.value=r.districtCode);window.scrollTo({top:0,behavior:'smooth'})}
async function action(r:ShippingRule,name:'publish'|'retire'|'invalidate'){if(name==='invalidate'&&!window.confirm(t('Invalidate this revision immediately? Existing unconsumed quotes will be rejected.')))return;busy.value=true;try{await api.transitionShippingRule(r.id,name);await load()}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{busy.value=false}}
onMounted(load)
</script>
<template><div class="operations-page"><header class="page-heading"><h1>{{t('Shipping rate revisions')}}</h1><p>{{t('Published financial revisions are immutable. Create a new revision to change a fee.')}}</p></header><p v-if="error" class="form-error" role="alert">{{error}}</p>
<form class="report-controls" @submit.prevent="create"><label>{{t('Location')}}<select v-model="location" :required="scope==='LOCATION'" :disabled="scope==='GLOBAL'"><option value="" disabled>{{scope==='GLOBAL'?'GLOBAL':'—'}}</option><option v-for="l in locations" :key="l.id" :value="l.id">{{l.branchCode}} · {{l.code}} · {{l.name}}</option></select></label><label>{{t('Province / city')}}<select v-model="province" required><option value="" disabled>—</option><option v-for="p in provinces" :key="p.code" :value="p.code">{{p.label}}</option></select></label><label>{{t('District')}}<select v-model="district" required :disabled="!province"><option value="" disabled>—</option><option v-for="d in districts" :key="d.code" :value="d.code">{{d.label}}</option></select></label><label>{{t('Zone')}}<select v-model="zone"><option>LOCAL_CORE</option><option>LOCAL_OUTER</option><option>INTER_PROVINCE</option></select></label><label>{{t('Fee')}}<input v-model.number="fee" type="number" min="0" step="1" required /></label><label>{{t('Priority')}}<input v-model.number="priority" type="number" required /></label><button :disabled="busy">{{t(family?'Create new revision':'Create draft')}}</button></form>
<div class="table-shell"><table><thead><tr><th>{{t('Rule family')}}</th><th>{{t('Revision')}}</th><th>{{t('Scope')}}</th><th>{{t('Destination')}}</th><th>{{t('Zone')}}</th><th>{{t('Fee')}}</th><th>{{t('Priority')}}</th><th>{{t('Effective period')}}</th><th>{{t('State')}}</th><th>{{t('Actions')}}</th></tr></thead><tbody><tr v-for="r in rules" :key="r.id"><td>{{r.familyId}}</td><td>{{r.revisionNumber}}</td><td>{{r.originScope}}<br>{{r.originLocationId}}</td><td>{{r.provinceCode}} / {{r.districtCode||'*'}}</td><td>{{r.zoneCode}}</td><td>{{formatVnd(r.feeAmount)}}</td><td>{{r.priority}}</td><td>{{new Date(r.validFrom).toLocaleString()}}<br>→ {{r.validTo?new Date(r.validTo).toLocaleString():'∞'}}</td><td>{{r.status}}</td><td><button v-if="r.status==='DRAFT'" @click="action(r,'publish')">{{t('Publish')}}</button><button v-if="r.status==='PUBLISHED'" @click="nextRevision(r)">{{t('Create new revision')}}</button><button v-if="r.status==='PUBLISHED'" @click="action(r,'retire')">{{t('Retire')}}</button><button v-if="r.status==='PUBLISHED'" class="danger-button" @click="action(r,'invalidate')">{{t('Invalidate')}}</button></td></tr></tbody></table></div></div></template>
